import{_ as e,o as i,c as a,aw as l}from"./chunks/framework.DLufY-ao.js";const E=JSON.parse('{"title":"E2E-тесты","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/testing/testing/pyramid/e2e-test.md","filePath":"wiki/dev-commit/testing/testing/pyramid/e2e-test.md"}'),n={name:"wiki/dev-commit/testing/testing/pyramid/e2e-test.md"};function s(o,t,r,d,_,m){return i(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="e2e-тесты" tabindex="-1">E2E-тесты <a class="header-anchor" href="#e2e-тесты" aria-label="Permalink to &quot;E2E-тесты&quot;">​</a></h1><ul><li><strong>E2E (End-to-End) или сквозные тесты</strong> тестирование всей системы от начала до конца, тестирование пользовательских функций. Это включает в себя обеспечение того, чтобы все интегрированные части приложения функционировали и работали вместе, как ожидалось. E2E тесты моделируют реальные сценарии пользователя, в основном проверяя, как реальный пользователь будет использовать приложение</li><li>Эмулируют реальную пользовательскую среду. В интернете это тесты, запущенные в браузере, имитирующие щелчки мышью и нажатия клавиш</li><li>Тесты черного ящика</li><li>Кроме того, эти тесты запускаются как можно чаще, чтобы обеспечить обратную связь и добавить понимания что наша система осталась рабочей</li><li>Тесты E2E позволяют нам охватывать разделы приложения, которые не проверяются unit тестами и интеграционными тестами. Это связано с тем, что unit тесты и интеграционные тесты покрывают отдельные части приложения и тестируют изолированную часть функционала. Даже если эти части работают хорошо сами по себе, вы не уверены, будут ли они работать вместе. Таким образом, наличие набора E2E тестов поверх unit и интеграции позволяет нам тестировать все наше приложение</li></ul><ol><li>Открытие сайта в браузере и поиск определенных элементов</li><li>Затем заполнить несколько форм регистрации</li><li>Затем убедитесь, что пользователь успешно создан</li></ol>',3)])])}const p=e(n,[["render",s]]);export{E as __pageData,p as default};
